begin;
select plan(41);

select has_table('public','checklist_issue_evidence','normalized evidence table exists');
select ok((select not public and file_size_limit=5242880 and allowed_mime_types=array['image/jpeg','image/png','image/webp'] from storage.buckets where id='checklist-issue-evidence'),'evidence bucket is private and byte/MIME bounded');
select ok((select relrowsecurity from pg_class where oid='public.checklist_issue_evidence'::regclass),'evidence RLS enabled');
select ok(not has_table_privilege('anon','public.checklist_issue_evidence','select') and not has_table_privilege('authenticated','public.checklist_issue_evidence','insert') and not has_table_privilege('service_role','public.checklist_issue_evidence','update'),'no direct evidence-table access including service role');
select is((select count(*) from pg_policies where schemaname='storage' and tablename='objects' and (qual ilike '%checklist-issue-evidence%' or with_check ilike '%checklist-issue-evidence%')),0::bigint,'no browser storage policy grants evidence access');
select ok(not has_function_privilege('anon','public.authorize_phase4a_evidence_upload(uuid,uuid,text,text)','execute') and not has_function_privilege('authenticated','public.authorize_phase4a_evidence_upload(uuid,uuid,text,text)','execute') and has_function_privilege('service_role','public.authorize_phase4a_evidence_upload(uuid,uuid,text,text)','execute'),'upload authorization RPC is service-only');
select ok(not has_function_privilege('authenticated','public.register_phase4a_evidence_upload(uuid,uuid,text,text,uuid,text,text,bigint,text)','execute') and has_function_privilege('service_role','public.register_phase4a_evidence_upload(uuid,uuid,text,text,uuid,text,text,bigint,text)','execute'),'registration RPC is service-only');
select ok(not has_function_privilege('authenticated','public.authorize_phase4a_evidence_read(uuid,uuid)','execute') and has_function_privilege('service_role','public.authorize_phase4a_evidence_read(uuid,uuid)','execute'),'read authorization RPC is service-only');
select is((select proconfig from pg_proc where oid='public.register_phase4a_evidence_upload(uuid,uuid,text,text,uuid,text,text,bigint,text)'::regprocedure),array['search_path=""'],'registration RPC has empty search path');
select has_index('public','checklist_issue_evidence','checklist_issue_evidence_org_report_idx','organization/report index exists');
select has_index('public','checklist_issue_evidence','checklist_issue_evidence_team_date_idx','team/date index exists');
select has_index('public','checklist_issue_evidence','checklist_issue_evidence_pending_expiry_idx','pending expiry index exists');
select has_index('public','checklist_issue_evidence','checklist_issue_evidence_final_result_key','final result uniqueness exists');
select is((select count(*) from information_schema.columns where table_schema='public' and table_name='checklist_issue_evidence' and column_name in('password','pin','token','cookie','email','signed_url','image_bytes','base64')),0::bigint,'evidence rows contain no secret, signed URL, or image-byte columns');

insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',id,'authenticated','authenticated',id||'@example.invalid','{}','{}',now(),now() from unnest(array['1a000000-0000-4000-8000-000000000001'::uuid,'1a000000-0000-4000-8000-000000000002','1a000000-0000-4000-8000-000000000003','1a000000-0000-4000-8000-000000000004'])id;
update public.profiles set full_name=case when id='1a000000-0000-4000-8000-000000000003' then'Manager'else'Supervisor'end,must_change_password=false where id::text like'1a000000-%';
insert into public.organizations(id,name,slug)values('2a000000-0000-4000-8000-000000000001','Evidence Org','evidence-org'),('2a000000-0000-4000-8000-000000000002','Other Org','evidence-other');
insert into public.branches(id,organization_id,name,code,timezone)values('3a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','Evidence Branch','EV','Asia/Riyadh'),('3a000000-0000-4000-8000-000000000002','2a000000-0000-4000-8000-000000000002','Other Branch','OT','UTC');
insert into public.organization_memberships(organization_id,user_id,role)values('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000003','organization_manager');
insert into public.branch_memberships(branch_id,user_id,role)values('3a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','branch_manager'),('3a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000002','branch_manager'),('3a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000004','staff');
insert into public.branch_supervisor_teams(id,organization_id,branch_id,supervisor_user_id)values('4a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001'),('4a000000-0000-4000-8000-000000000002','2a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000002');

select lives_ok($$select * from public.authorize_phase4a_evidence_upload('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening','kitchen-opening-1')$$,'authorized Supervisor and item accepted');
select throws_ok($$select * from public.authorize_phase4a_evidence_upload('1a000000-0000-4000-8000-000000000003','3a000000-0000-4000-8000-000000000001','kitchen_opening','kitchen-opening-1')$$,'42501','evidence upload denied','Manager cannot upload');
select throws_ok($$select * from public.authorize_phase4a_evidence_upload('1a000000-0000-4000-8000-000000000004','3a000000-0000-4000-8000-000000000001','kitchen_opening','kitchen-opening-1')$$,'42501','evidence upload denied','legacy Staff cannot upload');
select throws_ok($$select * from public.authorize_phase4a_evidence_upload('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','foh_opening','kitchen-opening-1')$$,'42501','evidence upload denied','cross-checklist item denied');
select lives_ok($$select * from public.register_phase4a_evidence_upload('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening','kitchen-opening-1','5a000000-0000-4000-8000-000000000001','opaque/tenant/team/date/5a000000-0000-4000-8000-000000000001.jpg','image/jpeg',128,repeat('a',64))$$,'pending evidence registered');
select is((select status from public.checklist_issue_evidence where id='5a000000-0000-4000-8000-000000000001'),'pending','registered evidence is pending');
select lives_ok($$select * from public.authorize_phase4a_evidence_set('1a000000-0000-4000-8000-000000000002','3a000000-0000-4000-8000-000000000001','kitchen_opening',array['5a000000-0000-4000-8000-000000000001'::uuid])$$,'same-branch Supervisor can reuse branch-owned Opening evidence');

select lives_ok($$select public.save_phase4a_draft('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening',0,(select jsonb_agg(jsonb_build_object('item_id','kitchen-opening-'||n,'answer',case when n=1 then'issue_found'else'completed'end,'remark',case when n=1 then' Evidence required 'else''end,'evidence_id',case when n=1 then to_jsonb('5a000000-0000-4000-8000-000000000001'::text)else'null'::jsonb end)order by n)from generate_series(1,17)n))$$,'draft links evidence');
select is((select status from public.checklist_issue_evidence where id='5a000000-0000-4000-8000-000000000001'),'draft','pending becomes draft');
select ok((select draft_result_id is not null and draft_submission_id is not null and expires_at is null from public.checklist_issue_evidence where id='5a000000-0000-4000-8000-000000000001'),'draft linkage and expiry are correct');
select is((public.get_phase4a_current_state('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening')->'answers'->0->'evidence'->>'id'),'5a000000-0000-4000-8000-000000000001','draft DTO restores safe evidence metadata');
select throws_ok($$select public.submit_phase4a_opening('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening',1,'6a000000-0000-4000-8000-000000000001',repeat('b',64),(select jsonb_agg(jsonb_build_object('item_id','kitchen-opening-'||n,'answer',case when n=1 then'issue_found'else'completed'end,'remark',case when n=1 then'Issue'else''end,'evidence_id',case when n=1 then to_jsonb('5a000000-0000-4000-8000-000000000099'::text)else'null'::jsonb end)order by n)from generate_series(1,17)n))$$,'42501','evidence finalization denied','unbound evidence rolls final submission back');
select is((select count(*)from public.checklist_submissions where organization_id='2a000000-0000-4000-8000-000000000001' and branch_id='3a000000-0000-4000-8000-000000000001' and supervisor_team_id='4a000000-0000-4000-8000-000000000001' and checklist_type='kitchen_opening' and state='submitted'),0::bigint,'failed finalization creates no final report');
select is((select status from public.checklist_issue_evidence where id='5a000000-0000-4000-8000-000000000001'),'draft','failed finalization leaves draft evidence intact');
select lives_ok($$select public.submit_phase4a_opening('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening',1,'6a000000-0000-4000-8000-000000000002',repeat('c',64),(select jsonb_agg(jsonb_build_object('item_id','kitchen-opening-'||n,'answer',case when n=1 then'issue_found'else'completed'end,'remark',case when n=1 then' Issue final 'else''end,'evidence_id',case when n=1 then to_jsonb('5a000000-0000-4000-8000-000000000001'::text)else'null'::jsonb end)order by n)from generate_series(1,17)n))$$,'final submit succeeds');
select ok((select status='finalized'and final_result_id is not null and final_submission_id is not null and finalized_at is not null from public.checklist_issue_evidence where id='5a000000-0000-4000-8000-000000000001'),'evidence finalized atomically');
select is((select count(*)from public.checklist_issues i join public.checklist_issue_evidence e on e.final_result_id=i.opening_result_id where e.id='5a000000-0000-4000-8000-000000000001'),1::bigint,'generated issue links through immutable opening result');
select lives_ok($$select public.submit_phase4a_opening('1a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','kitchen_opening',1,'6a000000-0000-4000-8000-000000000002',repeat('c',64),(select jsonb_agg(jsonb_build_object('item_id','kitchen-opening-'||n,'answer',case when n=1 then'issue_found'else'completed'end,'remark',case when n=1 then' Issue final 'else''end,'evidence_id',case when n=1 then to_jsonb('5a000000-0000-4000-8000-000000000001'::text)else'null'::jsonb end)order by n)from generate_series(1,17)n))$$,'identical replay is idempotent');
select is((select count(*)from public.checklist_issue_evidence where id='5a000000-0000-4000-8000-000000000001' and status='finalized'),1::bigint,'replay does not duplicate evidence');
select throws_ok($$update public.checklist_issue_evidence set mime_type='image/png'where id='5a000000-0000-4000-8000-000000000001'$$,'55000','finalized evidence is immutable','final evidence cannot be mutated');
select throws_ok($$select * from public.retire_phase4a_evidence('1a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000001')$$,'42501','evidence delete denied','final evidence cannot be deleted');
update public.branch_supervisor_teams set active=false where id='4a000000-0000-4000-8000-000000000001';
select lives_ok($$select * from public.authorize_phase4a_evidence_read('1a000000-0000-4000-8000-000000000001','5a000000-0000-4000-8000-000000000001')$$,'owner reads historical evidence after team deactivation');
select lives_ok($$select * from public.authorize_phase4a_evidence_read('1a000000-0000-4000-8000-000000000003','5a000000-0000-4000-8000-000000000001')$$,'managed-organization Manager reads final evidence');
select lives_ok($$select * from public.authorize_phase4a_evidence_read('1a000000-0000-4000-8000-000000000002','5a000000-0000-4000-8000-000000000001')$$,'same-branch Supervisor reads branch-owned final evidence');
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values('00000000-0000-0000-0000-000000000000','1a000000-0000-4000-8000-000000000005','authenticated','authenticated','cross-branch@example.invalid','{}','{}',now(),now()),
('00000000-0000-0000-0000-000000000000','1a000000-0000-4000-8000-000000000006','authenticated','authenticated','cross-org@example.invalid','{}','{}',now(),now());
update public.profiles set full_name='Other Supervisor',must_change_password=false where id in('1a000000-0000-4000-8000-000000000005','1a000000-0000-4000-8000-000000000006');
insert into public.branches(id,organization_id,name,code,timezone)values('3a000000-0000-4000-8000-000000000003','2a000000-0000-4000-8000-000000000001','Other Same Org Branch','OS','Asia/Riyadh');
insert into public.branch_memberships(branch_id,user_id,role)values('3a000000-0000-4000-8000-000000000003','1a000000-0000-4000-8000-000000000005','branch_manager'),('3a000000-0000-4000-8000-000000000002','1a000000-0000-4000-8000-000000000006','branch_manager');
insert into public.branch_supervisor_teams(id,organization_id,branch_id,supervisor_user_id)values('4a000000-0000-4000-8000-000000000003','2a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000003','1a000000-0000-4000-8000-000000000005'),('4a000000-0000-4000-8000-000000000004','2a000000-0000-4000-8000-000000000002','3a000000-0000-4000-8000-000000000002','1a000000-0000-4000-8000-000000000006');
select throws_ok($$select * from public.authorize_phase4a_evidence_set('1a000000-0000-4000-8000-000000000005','3a000000-0000-4000-8000-000000000003','kitchen_opening',array['5a000000-0000-4000-8000-000000000001'::uuid])$$,'42501','evidence set denied','cross-branch Supervisor cannot reuse branch-owned evidence');
select throws_ok($$select * from public.authorize_phase4a_evidence_set('1a000000-0000-4000-8000-000000000006','3a000000-0000-4000-8000-000000000002','kitchen_opening',array['5a000000-0000-4000-8000-000000000001'::uuid])$$,'42501','evidence set denied','cross-organization Supervisor cannot reuse branch-owned evidence');
update public.profiles set disabled_at=now() where id='1a000000-0000-4000-8000-000000000002';
select throws_ok($$select * from public.authorize_phase4a_evidence_set('1a000000-0000-4000-8000-000000000002','3a000000-0000-4000-8000-000000000001','kitchen_opening',array['5a000000-0000-4000-8000-000000000001'::uuid])$$,'42501','evidence set denied','disabled same-branch Supervisor cannot reuse evidence');

select * from finish();
rollback;
